# =====================================================
# LOGIN GATE
# =====================================================
#
# Autentikasi sederhana berbasis session_state + password hashing (SHA-256 + salt).
# Tidak butuh library eksternal tambahan (streamlit-authenticator dsb) supaya tetap
# ringan di-deploy. CATATAN PENTING UNTUK PRODUKSI:
#   - Kredensial di bawah ini HARUS dipindah ke st.secrets (Streamlit Cloud "Secrets")
#     atau environment variable / database — JANGAN commit password asli ke repo.
#   - Untuk multi-user dengan role granular / audit log, pertimbangkan backend
#     database (mis. Postgres + tabel users) daripada dict di kode.
import hashlib
import hmac
import secrets as _secrets_mod

def _hash_password(password: str, salt: str) -> str:
    return hashlib.sha256((salt + password).encode("utf-8")).hexdigest()

def _load_user_db():
    """Ambil kredensial dari st.secrets kalau tersedia (disarankan untuk produksi),
    fallback ke default demo (WAJIB diganti sebelum dipakai di lapangan)."""
    try:
        if "auth_users" in st.secrets:
            return dict(st.secrets["auth_users"])
    except Exception:
        pass  # st.secrets belum dikonfigurasi -> pakai fallback demo di bawah
    # ---- fallback default (GANTI SEBELUM PRODUKSI) ----
    default_salt = "geoai-default-salt-ganti-ini"
    return {
        "admin": {
            "name": "Administrator",
            "role": "admin",
            "salt": default_salt,
            "password_hash": _hash_password("admin123", default_salt),
        },
        "surveyor": {
            "name": "Surveyor Lapangan",
            "role": "user",
            "salt": default_salt,
            "password_hash": _hash_password("surveyor123", default_salt),
        },
    }

USER_DB = _load_user_db()


def _is_admin_user():
    """True hanya untuk role admin. Dipakai untuk menyembunyikan tab/catatan
    teknis dari user surveyor supaya tampilan yang dipublikasikan tetap
    ringkas & profesional untuk pengguna lapangan."""
    return st.session_state.get("auth_role") == "admin"


def _ui_info(*args, **kwargs):
    """Pengganti st.info() -- disembunyikan sepenuhnya untuk user surveyor."""
    if _is_admin_user():
        st.info(*args, **kwargs)


def _ui_warning(*args, **kwargs):
    """Pengganti st.warning() -- disembunyikan sepenuhnya untuk user surveyor
    (biasanya berisi catatan teknis/keterbatasan model, bukan hal yang perlu
    diketahui pengguna lapangan)."""
    if _is_admin_user():
        st.warning(*args, **kwargs)


def _ui_caption(*args, **kwargs):
    """Pengganti st.caption() KHUSUS untuk catatan metodologi/teknis/disclaimer
    (bukan instruksi cara pakai) -- disembunyikan untuk user surveyor supaya
    tampilan yang dipakai di lapangan tetap ringkas & profesional."""
    if _is_admin_user():
        st.caption(*args, **kwargs)


