def _project_dump(payload, fileobj):
    """Tulis payload project sebagai pickle terkompresi gzip (jauh lebih kecil utk array numpy)."""
    with gzip.GzipFile(fileobj=fileobj, mode="wb", compresslevel=3) as _gz:
        pickle.dump(payload, _gz, protocol=pickle.HIGHEST_PROTOCOL)


