_MAX_PROJECT_UNCOMPRESSED = 1_500_000_000  # batas ukuran setelah dekompresi (cegah "zip bomb")


class _LimitedReader:
    def __init__(self, f, limit=_MAX_PROJECT_UNCOMPRESSED):
        self._f, self._limit, self._n = f, limit, 0

    def _count(self, data):
        self._n += len(data)
        if self._n > self._limit:
            raise ValueError("Isi file project terlalu besar setelah dekompresi (dibatasi demi keamanan).")
        return data

    def read(self, n=-1):
        return self._count(self._f.read(n))

    def readline(self, *a):
        return self._count(self._f.readline(*a))


class _ProjectUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        if module.startswith("streamlit"):
            return _PlainState
        if (module, name) in _PROJECT_PICKLE_ALLOW or os.environ.get("EROSI_ALLOW_UNSAFE_PROJECT_PICKLE") == "1":
            return super().find_class(module, name)
        raise pickle.UnpicklingError(
            f"File project berisi objek yang tidak diizinkan ({module}.{name}). Demi keamanan hanya data "
            f"project standar yang boleh dimuat -- file ini mungkin bukan buatan aplikasi ini atau berasal "
            f"dari versi yang sangat berbeda.")


def _project_load(fileobj):
    """Baca payload project; otomatis mendeteksi gzip (baru) atau pickle polos (file lama).
    Melempar ValueError berpesan jelas kalau isinya bukan file project (mis. halaman HTML hasil
    download yang gagal) dan menolak objek berbahaya (Unpickler allowlist)."""
    _head = fileobj.read(64)
    fileobj.seek(0)
    if _head.lstrip()[:1] == b"<":
        raise ValueError(
            "Isi file adalah halaman web (HTML), bukan file project -- kemungkinan proses download tadi "
            "gagal. Unduh ulang file project dari aplikasi (pakai tombol Download atau cara alternatif).")
    if _head[:2] == b"\x1f\x8b":
        with gzip.GzipFile(fileobj=fileobj, mode="rb") as _gz:
            _payload = _ProjectUnpickler(_LimitedReader(_gz)).load()
    else:
        _payload = _ProjectUnpickler(_LimitedReader(fileobj)).load()
    if not isinstance(_payload, dict) or not isinstance(_payload.get("state"), dict):
        raise ValueError("Struktur file project tidak dikenali (bukan file .eroproj buatan aplikasi ini).")
    return _payload


def _project_user_dir(username):
    _safe_user = re.sub(r"[^a-zA-Z0-9_.-]", "_", username or "unknown")
    _d = os.path.join(PROJECTS_ROOT, _safe_user)
    os.makedirs(_d, exist_ok=True)
    return _d


def _project_slug(name):
    _slug = re.sub(r"[^a-zA-Z0-9_-]+", "-", (name or "").strip().lower()).strip("-")
    return _slug or f"project-{int(time.time())}"


def _project_index_path(username):
    return os.path.join(_project_user_dir(username), "index.json")


def _load_project_index(username):
    _path = _project_index_path(username)
    _idx = []
    if os.path.exists(_path):
        try:
            with open(_path, "r", encoding="utf-8") as _f:
                _idx = json.load(_f) or []
        except Exception:
            _idx = []
    # Sinkronkan dengan isi folder: buang entri yatim (file .eroproj-nya tidak ada) dan
    # tambahkan file .eroproj yang ada di folder tapi belum tercatat di index.json.
    _d = _project_user_dir(username)
    _idx = [p for p in _idx if os.path.exists(os.path.join(_d, f"{p.get('slug')}.eroproj"))]
    _known = {p.get("slug") for p in _idx}
    try:
        for _fn in os.listdir(_d):
            if _fn.lower().endswith(".eroproj") and _fn[:-8] not in _known:
                _sl = _fn[:-8]
                _mt = os.path.getmtime(os.path.join(_d, _fn))
                _idx.append({
                    "name": _sl, "slug": _sl, "owner": username,
                    "saved_at": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(_mt)),
                    "n_segments": 0, "n_sections": 0, "analysis_done": False,
                    "note": "(dipulihkan dari file di folder; index.json tidak sinkron)",
                })
    except Exception:
        pass
    _idx.sort(key=lambda p: p.get("saved_at", ""), reverse=True)
    return _idx


def _save_project_index(username, index_list):
    with open(_project_index_path(username), "w", encoding="utf-8") as _f:
        json.dump(index_list, _f, ensure_ascii=False, indent=2)


def _is_uploaded_file_like(obj):
    return hasattr(obj, "getvalue") and hasattr(obj, "seek") and hasattr(obj, "name")


class _RestoredUploadedFile(io.BytesIO):
    """Pengganti ringan utk objek UploadedFile Streamlit ketika sebuah project
    dibuka kembali. Mendukung .seek()/.read() persis seperti aslinya (dipakai
    oleh save_uploaded_dxf & _save_uploaded_file_keep_ext di modul ini), plus
    atribut .name -- jadi kode yang sudah ada tidak perlu tahu bedanya."""

    def __init__(self, data, name):
        super().__init__(data)
        self.name = name


def _set_injected_upload(key, data_bytes, filename):
    """Suntikkan file (DXF, dsb) secara programatis untuk key upload tertentu,
    TANPA menulis ke key widget file_uploader itu sendiri.

    PENTING: Streamlit MELARANG nilai widget file_uploader di-set lewat
    st.session_state -- akan langsung raise StreamlitValueAssignmentNotAllowedError
    begitu widget-nya dipanggil (dikonfirmasi lewat AppTest). Jadi file yang
    di-inject disimpan di key BAYANGAN terpisah ({key}__injected); baca lewat
    _get_upload(key), yang mengutamakan file upload manual dari widget dan baru
    jatuh ke file injeksian ini kalau widget-nya kosong. Dipakai oleh fitur
    Project (memulihkan file yang disimpan) dan fitur kirim DXF revisi dari
    Rekonstruksi Desain ke Erosion Mapping."""
    st.session_state[f"{key}__injected"] = {"name": filename, "data": data_bytes}


def _get_upload(key):
    """Baca nilai upload untuk `key`: utamakan file yang benar-benar diupload user
    lewat widget (st.session_state[key]); kalau kosong, pakai file yang
    disuntikkan programatis lewat _set_injected_upload, dibungkus jadi
    _RestoredUploadedFile supaya kompatibel dengan kode pembaca DXF yang sudah
    ada (butuh .seek()/.read()/.name persis seperti UploadedFile asli)."""
    _live = st.session_state.get(key)
    if _live is not None:
        return _live
    _inj = st.session_state.get(f"{key}__injected")
    if _inj is not None:
        return _RestoredUploadedFile(_inj["data"], _inj.get("name", "file"))
    return None


def _collect_project_state(light=False, inputs_only=False):
    """Kumpulkan seluruh session_state yang relevan sebagai satu project,
    kecuali key yang di-exclude (auth, navigasi halaman, widget project itu
    sendiri) dan key widget internal yang tidak relevan disimpan ulang.
    Objek upload file (DXF/orthophoto/dsb) dikonversi jadi bytes mentah
    supaya bisa di-pickle & dipulihkan lagi nanti."""
    _snapshot = {}
    _skipped = []
    _PROJECT_LAST_SIZES.clear()
    for _k, _v in list(st.session_state.items()):
        if _k in _PROJECT_EXCLUDE_KEYS or _k.startswith(_PROJECT_EXCLUDE_PREFIXES):
            continue
        if light and _k.startswith(_PROJECT_LIGHT_EXCLUDE_PREFIXES):
            continue
        if inputs_only and (_k in _PROJECT_RESULT_KEYS or _k.startswith(_PROJECT_RESULT_PREFIXES)):
            continue
        if _is_widget_event_key(_k, _v) or "FormSubmitter" in _k:
            # key internal widget Plotly click-select / form -- isinya event,
            # bukan data project, dan seringkali tidak bisa di-pickle.
            continue
        # PERBAIKAN BUG BESAR (StreamlitValueAssignmentNotAllowedError saat buka project):
        # deteksi "ini key tombol" SEBELUMNYA memakai daftar pola nama (endswith/startswith)
        # yang ternyata jauh dari lengkap -- banyak tombol lain (mis. "del_{sid}",
        # "cover_del_{i}", "xs_draw_save", "design_recon_run", "flood_run_{sid}", dst) tidak
        # tertangkap, sehingga tetap ikut tersimpan dan bikin project GAGAL DIBUKA LAGI
        # persis dengan error ini begitu tombol yang bersangkutan dipanggil ulang.
        #
        # Pendekatan baru dibalik: st.button/download_button/form_submit_button SEMUANYA
        # melarang value-nya di-set lewat session_state, apa pun nama key-nya -- jadi
        # SEMUA key bernilai bool TIDAK disimpan secara default, KECUALI key yang memang
        # dikenal sebagai st.checkbox (yang justru PERLU persist, mis. "pakai hidraulika").
        # Checkbox baru yang ditambahkan nanti tinggal didaftarkan di tuple ini.
        _KNOWN_CHECKBOX_KEY_PREFIXES = (
            "anim_toggle_", "design_recon_use_interval", "dxf_overlay_3d_",
            "md_only_calibrated", "md_only_color_change", "md_show_debug",
            "rain_anim_toggle_", "show_ortho_overlay_", "show_sat_overlay_",
            "use_hydraulics_",
            # PERBAIKAN: flag status (bukan tombol) -- WAJIB ikut tersimpan. Tanpa ini project yang
            # dibuka selalu kembali analysis_done=False sehingga seluruh blok hasil analisis
            # (Erosion Mapping, Cross Section, Report) tidak ditampilkan walau datanya ada.
            "analysis_done",
        )
        if isinstance(_v, bool) and not _k.startswith(_KNOWN_CHECKBOX_KEY_PREFIXES):
            continue
        if _v is None:
            # PERBAIKAN BUG: banyak widget upload (orthophoto, reviewer_signature,
            # section_polyline, dst) OPSIONAL -- kalau belum diisi, nilainya None.
            # Kalau None ini ikut tersimpan lalu di-assign balik ke
            # st.session_state[key] saat restore, Streamlit akan crash
            # (StreamlitValueAssignmentNotAllowedError) begitu widget file_uploader
            # dengan key yang sama dipanggil -- widget upload MELARANG value-nya
            # di-set lewat session_state, apa pun isinya, termasuk None. Solusinya:
            # key bernilai None sama sekali tidak perlu disimpan -- kalau key-nya
            # tidak ada di snapshot, widget-nya nanti otomatis kembali ke default
            # (kosong/None juga), hasilnya identik tanpa perlu assignment apa pun.
            continue
        try:
            if _is_uploaded_file_like(_v):
                _v.seek(0)
                _snapshot[_k] = {"__uploaded_file__": True, "name": getattr(_v, "name", "file"), "data": _v.getvalue()}
                _PROJECT_LAST_SIZES[_k] = len(_snapshot[_k]["data"])
                _v.seek(0)
            else:
                _PROJECT_LAST_SIZES[_k] = len(pickle.dumps(_v))  # tes bisa di-pickle + catat ukuran
                _snapshot[_k] = _v
        except Exception as _e_ser:
            # simpan nama key + alasan, supaya kegagalan tidak lagi diam-diam
            _skipped.append(f"{_k} ({type(_e_ser).__name__}: {str(_e_ser)[:80]})")
    return _snapshot, _skipped


# Key widget st.plotly_chart(on_select=...) / peta klik: isinya STATE EVENT seleksi, bukan data project.
# Streamlit MELARANG key ini di-set lewat session_state (StreamlitValueAssignmentNotAllowedError begitu
# chart-nya dirender) -- persis error "flow_click_map_seg_1 cannot be set using st.session_state" saat
# buka project. Karena itu TIDAK BOLEH disimpan maupun dipulihkan.
_WIDGET_STATE_KEY_PREFIXES = ("xs_draw_map", "ba_click_map", "flow_click_map")


def _is_widget_event_key(_k, _v=None):
    if _k.startswith(_WIDGET_STATE_KEY_PREFIXES) or "_click_map" in _k:
        return True
    # Objek internal Streamlit (mis. state seleksi chart) tidak boleh masuk project -- KECUALI file
    # upload (UploadedFile juga bertipe streamlit.*, tapi isinya DXF/orthophoto yang HARUS disimpan).
    if type(_v).__name__ == "_PlainState":
        return True
    # state data_editor ({"edited_rows","added_rows","deleted_rows"}) = state WIDGET: tak boleh di-assign lewat session_state
    if isinstance(_v, dict) and {"edited_rows", "added_rows", "deleted_rows"} <= set(_v.keys()):
        return True
    # model ML (sklearn/xgboost/dst) TIDAK disimpan di project: kelasnya terlalu banyak untuk allowlist
    # keamanan dan model bisa dilatih ulang dari data (df_clean) di tab Machine Learning.
    if type(_v).__module__.split(".")[0] in ("sklearn", "xgboost", "lightgbm", "catboost", "torch", "tensorflow", "keras"):
        return True
    if type(_v).__module__.startswith("streamlit") and not _is_uploaded_file_like(_v):
        return True
    # cadangan: bentuk state seleksi Plotly/dataframe ({"selection": {"points": [...], "point_indices": [...]}})
    if isinstance(_v, dict) and isinstance(_v.get("selection"), dict) and (
            "point_indices" in _v["selection"] or "points" in _v["selection"] or "rows" in _v["selection"]):
        return True
    return False


def _set_project_open_notice(name):
    """Simpan ringkasan 'project berhasil dibuka' utk ditampilkan SEKALI di halaman utama setelah
    rerun (pesan st.success yang dipanggil tepat sebelum st.rerun() tidak pernah sempat terlihat)."""
    _n_seg = len(st.session_state.get("segments", []) or [])
    _files = []
    for _k in st.session_state.keys():
        if isinstance(_k, str) and _k.endswith("__injected"):
            _inj = st.session_state.get(_k)
            if isinstance(_inj, dict):
                _files.append(f"{_inj.get('name', 'file')} ({len(_inj.get('data', b'')) / 1024:.0f} KB)")
    _done = bool(st.session_state.get("analysis_done", False))
    _msg = _t(f"✅ Project '{name}' berhasil dibuka — {_n_seg} segmen", f"✅ Project '{name}' opened — {_n_seg} segment(s)")
    if _files:
        _msg += _t(" · file dimuat: ", " · files loaded: ") + ", ".join(_files)
    else:
        _msg += _t(" · TIDAK ada file DXF/orthophoto di dalam project ini (upload ulang bila perlu)",
                   " · NO DXF/orthophoto files inside this project (re-upload if needed)")
    _msg += _t(" · hasil analisis ikut dipulihkan." if _done else
               " · project berisi input saja: tekan RUN ANALYSIS untuk menghitung ulang.",
               " · analysis results restored." if _done else
               " · project contains inputs only: press RUN ANALYSIS to recompute.")
    st.session_state["_project_open_notice"] = _msg


def _restore_project_state(snapshot):
    """Pulihkan snapshot session_state sebuah project.

    PERBAIKAN BUG: sebelumnya key non-file di-assign langsung ke
    st.session_state[_k] tanpa penjagaan. Kalau snapshot project (dari save
    project versi lama, atau dari mode edge lain) kebawa key tombol seperti
    'back_to_hub_btn', Streamlit MELARANG assignment itu begitu widget dengan
    key yang sama sudah sempat dirender lebih dulu di run yang sama --
    "cannot be modified after the widget ... is instantiated" -- dan
    membatalkan seluruh proses buka project. Key tombol/aksi sekali-pakai
    seperti ini tidak pernah bermakna untuk dipulihkan (nilainya cuma True
    sesaat waktu diklik), jadi di-skip diam-diam per key kalau assignment-nya
    ditolak, alih-alih membuat SELURUH project gagal dibuka gara-gara satu
    key yang tidak relevan."""
    for _k, _v in snapshot.items():
        if _is_widget_event_key(_k, _v):
            # project LAMA yang kadung menyimpan key state chart klik-peta: dilewati di sini
            continue
        if _v is None:
            # PERBAIKAN BUG: project lama (disimpan sebelum perbaikan ini) bisa saja
            # masih membawa key upload opsional bernilai None (mis. orthophoto yang
            # tidak diisi). Assignment None ke key widget file_uploader TETAP
            # terlarang sama seperti assignment nilai apa pun -- jadi tetap dilewati
            # di sisi restore juga, bukan cuma dicegah di sisi save saja.
            continue
        if isinstance(_v, dict) and _v.get("__uploaded_file__"):
            # PERBAIKAN BUG: sebelumnya file diassign langsung ke st.session_state[_k],
            # yaitu key widget file_uploader itu sendiri -- Streamlit MELARANG ini dan
            # akan crash (StreamlitValueAssignmentNotAllowedError) begitu widget-nya
            # dirender lagi. Sekarang disuntikkan ke key bayangan lewat
            # _set_injected_upload, dibaca balik lewat _get_upload() di tempat file
            # ini dipakai (kontur_dxf, boundary_dxf, orthophoto, dst).
            _set_injected_upload(_k, _v["data"], _v.get("name", "file"))
        else:
            # PERBAIKAN: try/except di bawah TIDAK cukup untuk key tombol seperti
            # "del_seg_1" -- error StreamlitValueAssignmentNotAllowedError untuk
            # tombol baru muncul BELAKANGAN, saat st.button(key=...) itu sendiri
            # dipanggil di bagian lain script (jauh setelah fungsi ini selesai),
            # BUKAN pada saat assignment st.session_state[_k] = _v di sini -- jadi
            # assignment-nya sendiri "berhasil" tanpa exception, tapi tetap bikin
            # crash belakangan begitu tombolnya dirender. Untuk project LAMA yang
            # kadung tersimpan dengan key tombol seperti ini (sebelum perbaikan di
            # _collect_project_state), key bool selain checkbox yang dikenal tetap
            # dilewati DI SINI JUGA -- bukan cuma dicegah di sisi simpan.
            _KNOWN_CHECKBOX_KEY_PREFIXES = (
                "anim_toggle_", "design_recon_use_interval", "dxf_overlay_3d_",
                "md_only_calibrated", "md_only_color_change", "md_show_debug",
                "rain_anim_toggle_", "show_ortho_overlay_", "show_sat_overlay_",
                "use_hydraulics_",
                "analysis_done",
            )
            if isinstance(_v, bool) and not _k.startswith(_KNOWN_CHECKBOX_KEY_PREFIXES):
                continue
            try:
                st.session_state[_k] = _v
            except Exception:
                # key milik widget yang sudah terlanjur diinstansiasi di run ini
                # (mis. tombol) -- lewati, bukan data project yang berarti.
                continue


def save_project(username, project_name, note="", inputs_only=False):
    """Simpan snapshot session_state saat ini sebagai project baru (atau
    menimpa project lama dengan slug/nama yang sama). Mengembalikan
    (slug, daftar_key_yang_dilewati_karena_tak_bisa_di-pickle)."""
    _slug = _project_slug(project_name)
    _snapshot, _skipped = _collect_project_state(inputs_only=inputs_only)
    _meta = {
        "name": project_name.strip() or _slug,
        "slug": _slug,
        "owner": username,
        "saved_at": pd.Timestamp.now().strftime("%Y-%m-%d %H:%M:%S"),
        "n_segments": len(st.session_state.get("segments", []) or []),
        "n_sections": 0 if inputs_only else len(st.session_state.get("section_results", {}) or {}),
        "analysis_done": False if inputs_only else bool(st.session_state.get("analysis_done", False)),
        "inputs_only": bool(inputs_only),
        "note": note or "",
    }
    _payload = {"meta": _meta, "state": _snapshot}
    _path = os.path.join(_project_user_dir(username), f"{_slug}.eroproj")
    # tulis ke file sementara dulu lalu ganti atomik -- kalau gagal di tengah jalan, project
    # lama yang sudah ada tidak rusak/terpotong, dan tidak ada file .eroproj setengah jadi.
    _tmp_path = _path + ".tmp"
    with open(_tmp_path, "wb") as _f:
        _project_dump(_payload, _f)
        _f.flush()
        try:
            os.fsync(_f.fileno())
        except OSError:
            pass
    os.replace(_tmp_path, _path)
    if (not os.path.exists(_path)) or os.path.getsize(_path) == 0:
        raise IOError(f"File project gagal ditulis: {_path}")

    _index_list = [p for p in _load_project_index(username) if p.get("slug") != _slug]
    _index_list.append(_meta)
    _index_list.sort(key=lambda p: p.get("saved_at", ""), reverse=True)
    _save_project_index(username, _index_list)
    return _slug, _skipped


def load_project(username, slug):
    """Muat kembali project tersimpan ke session_state saat ini. Mengembalikan
    metadata project yang dimuat."""
    _path = os.path.join(_project_user_dir(username), f"{slug}.eroproj")
    with open(_path, "rb") as _f:
        _payload = _project_load(_f)
    _restore_project_state(_payload["state"])
    return _payload["meta"]


def delete_project(username, slug):
    _path = os.path.join(_project_user_dir(username), f"{slug}.eroproj")
    if os.path.exists(_path):
        os.remove(_path)
    _index_list = [p for p in _load_project_index(username) if p.get("slug") != slug]
    _save_project_index(username, _index_list)


# =====================================================
# REKONSTRUKSI DESAIN CHANNEL (DXF)
# -----------------------------------------------------
# Membaca DXF desain channel, mengekstrak centerline & penampang eksisting,
# lalu membangun ulang geometri channel secara parametrik (lebar dasar,
# kedalaman, sudut slope kiri/kanan, jumlah & lebar bench/grading). Hasilnya
# diekspor kembali sebagai DXF 3D supaya bisa langsung dipakai engineer
# sebagai acuan revisi desain.
# =====================================================


def _dxf_read_polylines(path):
    """Ambil semua polyline (LWPOLYLINE/POLYLINE/LINE) dari DXF sebagai list
    of list-of-(x, y, z), lengkap dengan nama layer-nya. Dipakai untuk memilih
    centerline channel dan menampilkan geometri desain asli."""
    _doc = ezdxf.readfile(path)
    _msp = _doc.modelspace()
    _polys = []
    for _e in _msp:
        _typ = _e.dxftype()
        _layer = getattr(_e.dxf, "layer", "0")
        try:
            if _typ == "LWPOLYLINE":
                _elev = float(getattr(_e.dxf, "elevation", 0.0) or 0.0)
                _pts = [(float(p[0]), float(p[1]), _elev) for p in _e.get_points("xy")]
            elif _typ == "POLYLINE":
                _pts = [(float(v.dxf.location.x), float(v.dxf.location.y), float(v.dxf.location.z))
                        for v in _e.vertices]
            elif _typ == "LINE":
                _pts = [
                    (float(_e.dxf.start.x), float(_e.dxf.start.y), float(_e.dxf.start.z)),
                    (float(_e.dxf.end.x), float(_e.dxf.end.y), float(_e.dxf.end.z)),
                ]
            else:
                continue
        except Exception:
            continue
        if len(_pts) >= 2:
            _polys.append({"points": _pts, "layer": _layer, "type": _typ})
    return _polys


def _polyline_length_2d(points):
    _p = np.asarray(points, dtype=float)
    if len(_p) < 2:
        return 0.0
    return float(np.sum(np.hypot(np.diff(_p[:, 0]), np.diff(_p[:, 1]))))


def _resample_centerline(points, spacing):
    """Resample centerline jadi titik-titik berjarak ~spacing meter, plus hitung
    vektor arah (tangent) dan normal kiri di tiap stasiun. Normal inilah sumbu
    tempat template penampang ditempelkan."""
    _p = np.asarray(points, dtype=float)
    _seg = np.hypot(np.diff(_p[:, 0]), np.diff(_p[:, 1]))
    _cum = np.concatenate([[0.0], np.cumsum(_seg)])
    _total = float(_cum[-1])
    if _total <= 0:
        return None
    _n = max(int(np.ceil(_total / max(spacing, 0.1))) + 1, 2)
    _stations = np.linspace(0.0, _total, _n)

    _xs = np.interp(_stations, _cum, _p[:, 0])
    _ys = np.interp(_stations, _cum, _p[:, 1])
    _zs = np.interp(_stations, _cum, _p[:, 2]) if _p.shape[1] > 2 else np.zeros_like(_xs)

    _dx = np.gradient(_xs)
    _dy = np.gradient(_ys)
    _norm = np.hypot(_dx, _dy)
    _norm[_norm == 0] = 1e-9
    _tx, _ty = _dx / _norm, _dy / _norm
    # normal kiri = rotasi tangent +90 derajat
    _nx, _ny = -_ty, _tx

    return {
        "station": _stations, "x": _xs, "y": _ys, "z": _zs,
        "tx": _tx, "ty": _ty, "nx": _nx, "ny": _ny, "total_length": _total,
    }


def _channel_template_offsets(bottom_width, depth, slope_left_deg, slope_right_deg,
                              n_bench=0, bench_width=0.0, bench_interval=None,
                              top_extra=0.0):
    """Bangun template penampang channel simetris-parametrik dalam koordinat lokal
    (offset lateral, elevasi relatif terhadap invert). Urutan titik dari tepi atas
    KIRI -> turun ke dasar -> naik ke tepi atas KANAN, sehingga bisa langsung
    dijadikan polyline penampang.

    n_bench = jumlah bench/berm grading di TIAP sisi. Kalau > 0, tinggi total
    dibagi rata jadi beberapa lift, dan di antara lift disisipkan bidang datar
    selebar bench_width (inilah "menambah/mengurangi grading").
    """
    _sl = float(np.clip(slope_left_deg, 1.0, 89.0))
    _sr = float(np.clip(slope_right_deg, 1.0, 89.0))
    _hw = float(bottom_width) / 2.0
    _depth = float(depth)
    _nb = int(max(0, n_bench))

    if bench_interval and bench_interval > 0:
        _lift_h = float(bench_interval)
        _n_lift = max(int(np.ceil(_depth / _lift_h)), 1)
    else:
        _n_lift = _nb + 1
        _lift_h = _depth / _n_lift

    def _side(slope_deg, sign):
        """sign = -1 utk sisi kiri, +1 utk sisi kanan."""
        _run_per_lift = _lift_h / np.tan(np.radians(slope_deg))
        _pts = []
        _off = sign * _hw
        _elev = 0.0
        for _i in range(_n_lift):
            _h = min(_lift_h, _depth - _elev)
            if _h <= 0:
                break
            _off += sign * (_h / np.tan(np.radians(slope_deg)))
            _elev += _h
            _pts.append((_off, _elev))
            if _i < _n_lift - 1 and _nb > 0 and bench_width > 0:
                _off += sign * float(bench_width)
                _pts.append((_off, _elev))
        if top_extra > 0:
            _off += sign * float(top_extra)
            _pts.append((_off, _elev))
        return _pts

    _left = _side(_sl, -1)
    _right = _side(_sr, +1)
    # kiri dibalik supaya urut dari tepi atas kiri menuju dasar
    _profile = list(reversed(_left)) + [(-_hw, 0.0), (_hw, 0.0)] + _right
    return _profile


def _build_channel_geometry(cl, template_offsets, invert_z):
    """Tempelkan template penampang ke tiap stasiun centerline -> array 3D
    (n_station, n_template, 3) dalam koordinat dunia. invert_z bisa berupa
    skalar (invert datar) atau array sepanjang stasiun (mengikuti grade)."""
    _n_st = len(cl["station"])
    _tmpl = np.asarray(template_offsets, dtype=float)
    _n_t = len(_tmpl)
    _invert = np.full(_n_st, float(invert_z)) if np.isscalar(invert_z) else np.asarray(invert_z, dtype=float)

    _geom = np.zeros((_n_st, _n_t, 3))
    for _i in range(_n_st):
        _geom[_i, :, 0] = cl["x"][_i] + _tmpl[:, 0] * cl["nx"][_i]
        _geom[_i, :, 1] = cl["y"][_i] + _tmpl[:, 0] * cl["ny"][_i]
        _geom[_i, :, 2] = _invert[_i] + _tmpl[:, 1]
    return _geom


def _sample_existing_section(cl, station_idx, design_points_kdtree_xy, design_z,
                             offsets, search_radius):
    """Ambil elevasi desain EKSISTING di sepanjang garis penampang pada satu
    stasiun, dengan nearest-neighbour terhadap titik-titik DXF asli. Titik yang
    tidak punya tetangga dalam search_radius dikembalikan sebagai NaN supaya
    tidak dipakai sebagai pembanding palsu."""
    _px = cl["x"][station_idx] + offsets * cl["nx"][station_idx]
    _py = cl["y"][station_idx] + offsets * cl["ny"][station_idx]
    _query = np.column_stack([_px, _py])
    _dist, _idx = design_points_kdtree_xy.query(_query, k=1)
    _z = design_z[_idx].astype(float)
    _z[_dist > search_radius] = np.nan
    return _z


_re_cell_amp = re.compile(r"&(?!(?:amp|lt|gt|quot|apos|#\d+|#x[0-9a-fA-F]+);)")


def _np_trapz(y, x):
    """Integrasi trapesium yang aman lintas versi numpy: np.trapz dihapus di
    numpy 2.x dan diganti np.trapezoid, sedangkan numpy 1.x belum punya
    np.trapezoid — jadi dipilih otomatis sesuai versi yang terpasang."""
    _fn = getattr(np, "trapezoid", None) or getattr(np, "trapz")
    return float(_fn(y, x))


def _channel_cut_fill(existing_z, design_z_line, offsets):
    """Estimasi luas cut & fill (m2) pada satu penampang dengan aturan trapesium,
    mengabaikan bagian yang elevasi eksistingnya tidak diketahui (NaN)."""
    _valid = ~np.isnan(existing_z)
    if _valid.sum() < 2:
        return 0.0, 0.0
    _o = np.asarray(offsets)[_valid]
    _diff = np.asarray(design_z_line)[_valid] - existing_z[_valid]
    _cut_h = np.clip(-_diff, 0, None)   # desain di BAWAH eksisting -> galian
    _fill_h = np.clip(_diff, 0, None)   # desain di ATAS eksisting -> timbunan
    _cut_area = _np_trapz(_cut_h, _o)
    _fill_area = _np_trapz(_fill_h, _o)
    return _cut_area, _fill_area


def _export_channel_dxf(geom, cl, out_path, section_every=1, include_boundary=False):
    """Tulis geometri channel hasil rekonstruksi ke DXF 3D: stringline memanjang
    (mengikuti tiap titik template) + polyline penampang tiap beberapa stasiun +
    centerline. Layer dipisah supaya gampang dipakai/di-toggle engineer di CAD.

    include_boundary=True menambahkan SATU polyline TERTUTUP (layer REVISI_BOUNDARY)
    berupa footprint crest kiri + crest kanan desain -- dipakai saat DXF ini dikirim
    balik ke tab Erosion Mapping sebagai kontur SEKALIGUS boundary segmen baru, supaya
    desain revisi bisa langsung diuji-jalankan lagi di sana (lihat tombol "Kirim ke
    Erosion Mapping" di tab Rekonstruksi Desain)."""
    _doc = ezdxf.new("R2010")
    _msp = _doc.modelspace()
    _layers = [("REVISI_STRINGLINE", 3), ("REVISI_SECTION", 5), ("REVISI_CENTERLINE", 1)]
    if include_boundary:
        _layers.append(("REVISI_BOUNDARY", 2))
    for _ly, _col in _layers:
        if _ly not in _doc.layers:
            _doc.layers.add(_ly, color=_col)

    _n_st, _n_t, _ = geom.shape
    for _t in range(_n_t):
        _msp.add_polyline3d(
            [tuple(geom[_s, _t, :]) for _s in range(_n_st)],
            dxfattribs={"layer": "REVISI_STRINGLINE"},
        )
    for _s in range(0, _n_st, max(1, int(section_every))):
        _msp.add_polyline3d(
            [tuple(geom[_s, _t, :]) for _t in range(_n_t)],
            dxfattribs={"layer": "REVISI_SECTION"},
        )
    _msp.add_polyline3d(
        [(float(cl["x"][_s]), float(cl["y"][_s]), float(geom[_s, _n_t // 2, 2]))
         for _s in range(_n_st)],
        dxfattribs={"layer": "REVISI_CENTERLINE"},
    )

    if include_boundary:
        _left = [tuple(geom[_s, 0, :]) for _s in range(_n_st)]
        _right = [tuple(geom[_s, _n_t - 1, :]) for _s in range(_n_st - 1, -1, -1)]
        _footprint = _left + _right
        _msp.add_polyline3d(
            _footprint, close=True,
            dxfattribs={"layer": "REVISI_BOUNDARY"},
        )

    _doc.saveas(out_path)
    return out_path


