# =====================================================================
# CROSS SECTION -- helper bersama (layar Plotly + laporan PDF/DOCX)
# =====================================================================
# Penampang lama hanya menggambar garis elevasi 1-D. Versi ini membuat "tirai" (curtain) 2-D
# di bawah permukaan tanah -- mesh berlapis mengikuti topografi, diwarnai kontur rainbow
# (jet) dari parameter hasil analisis (risiko erosi, sedimentasi, kecepatan, dst), plus muka
# air. Catatan penting: di bawah permukaan TIDAK ada data terukur; warna kolom diambil dari nilai
# di permukaan lalu dipudarkan terhadap kedalaman (zona pengaruh, ilustratif).

_XS_PARAM_META = {
    # key: (label_id, label_en, satuan)
    "erosion": ("Indeks risiko erosi", "Erosion risk index", ""),
    "sediment": ("Intensitas sedimentasi", "Sedimentation intensity", ""),
    "velocity": ("Kecepatan aliran", "Flow velocity", "m/s"),
    "flow_density": ("Kepadatan aliran", "Flow density", ""),
    "slope_pct": ("Kemiringan lereng", "Slope", "%"),
    "overflow": ("Indeks overflow", "Overflow index", ""),
}
_XS_SHORT_LABEL = {
    "erosion": ("Risiko erosi", "Erosion risk"),
    "sediment": ("Sedimentasi", "Sedimentation"),
    "velocity": ("Kecepatan (m/s)", "Velocity (m/s)"),
    "flow_density": ("Kepadatan aliran", "Flow density"),
    "slope_pct": ("Kemiringan (%)", "Slope (%)"),
    "overflow": ("Overflow", "Overflow"),
}
_XS_PARAM_ORDER = ["erosion", "sediment", "velocity", "flow_density", "slope_pct", "overflow"]


def _xs_label(key):
    _m = _XS_PARAM_META[key]
    _txt = _t(_m[0], _m[1])
    return f"{_txt} ({_m[2]})" if _m[2] else _txt


def _xs_short(key):
    return _t(*_XS_SHORT_LABEL[key])


def _xs_param_array(r, key):
    _v = r.get(key)
    if _v is None:
        return None
    _v = np.asarray(_v, dtype=float)
    return _v if _v.shape == np.asarray(r["distance"]).shape else None


def _xs_available_params(r):
    _out = []
    for _k in _XS_PARAM_ORDER:
        _v = _xs_param_array(r, _k)
        if _v is not None and np.isfinite(_v).sum() >= 2:
            _out.append(_k)
    return _out


def _xs_sample_profile(vertices, grid_x, grid_y, grid_z, fields, inside=None):
    """Sampel profil sepanjang polyline dgn interpolasi BILINEAR (bukan nearest-neighbour
    yg menghasilkan garis bergerigi/tangga). fields = {nama: array_grid} ikut disampel."""
    from scipy.interpolate import RegularGridInterpolator

    _gxa = np.asarray(grid_x, dtype=float)
    _gx = _gxa[:, 0].copy()
    _gy = np.asarray(grid_y, dtype=float)[0, :].copy()
    _shape = _gxa.shape
    _flip_x = _gx[0] > _gx[-1]
    _flip_y = _gy[0] > _gy[-1]
    if _flip_x:
        _gx = _gx[::-1]
    if _flip_y:
        _gy = _gy[::-1]

    def _interp(F, pts):
        F = np.asarray(F, dtype=float)
        if F.shape != _shape:
            return None
        if _flip_x:
            F = F[::-1, :]
        if _flip_y:
            F = F[:, ::-1]
        return RegularGridInterpolator((_gx, _gy), F, method="linear",
                                       bounds_error=False, fill_value=np.nan)(pts)

    _vx = np.array([p[0] for p in vertices], dtype=float)
    _vy = np.array([p[1] for p in vertices], dtype=float)
    _seg = np.hypot(np.diff(_vx), np.diff(_vy))
    _cum = np.concatenate([[0.0], np.cumsum(_seg)])
    _total = float(_cum[-1])
    _cell = min(abs(_gx[1] - _gx[0]) if len(_gx) > 1 else 1.0,
                abs(_gy[1] - _gy[0]) if len(_gy) > 1 else 1.0)
    _n = int(np.clip(_total / max(_cell * 0.5, _total / 1500.0, 1e-6), 80, 1500))
    _s = np.linspace(0.0, _total, _n)
    _px = np.interp(_s, _cum, _vx)
    _py = np.interp(_s, _cum, _vy)
    _pts = np.column_stack([_px, _py])

    _z = _interp(grid_z, _pts)
    _out = {"distance": _s, "elevation": _z}
    if inside is not None:
        _ins = _interp(np.asarray(inside, dtype=float), _pts)
        _out["inside"] = (np.nan_to_num(_ins, nan=0.0) >= 0.5) if _ins is not None else None
    for _name, _F in fields.items():
        _a = _interp(_F, _pts) if _F is not None else None
        if _a is not None:
            _out[_name] = _a
    # kemiringan lereng sepanjang profil (%): dari elevasi yg sudah dihaluskan ringan
    _zf = _z.copy()
    _okz = np.isfinite(_zf)
    if _okz.sum() >= 3:
        _zf = np.interp(_s, _s[_okz], _zf[_okz])
        _w = 5
        _zs = np.convolve(np.pad(_zf, (_w // 2, _w // 2), mode="edge"), np.ones(_w) / _w, mode="valid")
        _out["slope_pct"] = np.abs(np.gradient(_zs, _s)) * 100.0
    # nilai di luar batas analisis => NaN (ditampilkan abu-abu, bukan hitam)
    if _out.get("inside") is not None:
        for _k in list(_out.keys()):
            if _k in ("distance", "elevation", "inside"):
                continue
            _out[_k] = np.where(_out["inside"], _out[_k], np.nan)
    return _out


def _xs_curtain(r, key="erosion", decay=True, thick=None, nx_max=240, ny=260, n_layers=10):
    """Bangun grid 2-D 'tirai' di bawah permukaan. Mengembalikan dict array siap plot."""
    _d = np.asarray(r["distance"], dtype=float)
    _z = np.asarray(r["elevation"], dtype=float)
    _v = _xs_param_array(r, key)
    _okz = np.isfinite(_z)
    if _v is None or _okz.sum() < 2 or len(_d) < 2:
        return None
    _z = np.interp(_d, _d[_okz], _z[_okz])

    _nx = int(min(len(_d), nx_max))
    _xg = np.linspace(_d[0], _d[-1], _nx)
    _zs = np.interp(_xg, _d, _z)
    _idx = np.clip(np.searchsorted(_d, _xg), 0, len(_d) - 1)

    _valid = np.isfinite(_v)
    if _valid.sum() < 1:
        return None
    _vv = np.interp(_xg, _d[_valid], _v[_valid])
    _vmask = _valid[_idx]
    _vv = np.where(_vmask, _vv, np.nan)

    _ins = r.get("inside")
    _outside = (~np.asarray(_ins, dtype=bool)[_idx]) if _ins is not None else (~_vmask)

    _yspan = max(float(np.ptp(_zs)), 0.5)
    _T = float(thick) if (thick and thick > 0) else max(0.35 * _yspan, 0.5)
    _ymax = float(_zs.max()) + 0.08 * _yspan
    _ymin = float(_zs.min()) - _T - 0.05 * _yspan
    _yc = np.linspace(_ymin, _ymax, ny)
    _dep = _zs[None, :] - _yc[:, None]
    _in = (_dep >= 0) & (_dep <= _T)

    _vmin = float(np.nanmin(_v))
    _vmax = float(np.nanmax(_v))
    if _vmax <= _vmin:
        _vmax = _vmin + 1e-6
    if decay:
        _L = _T / 2.2
        _val = _vmin + (_vv[None, :] - _vmin) * np.exp(-np.clip(_dep, 0, None) / _L)
    else:
        _val = np.broadcast_to(_vv[None, :], _dep.shape)
    _Z = np.round(np.where(_in & ~_outside[None, :] & np.isfinite(_val), _val, np.nan), 4)
    _Zg = np.where(_in & _outside[None, :], 1.0, np.nan)

    _lay = np.linspace(0.0, _T, n_layers + 1)[1:-1]
    return dict(xg=_xg, yc=_yc, Z=_Z, Zgray=_Zg, zs=_zs, vv=_vv, T=_T, layers=_lay,
                ymin=_ymin, ymax=_ymax, vmin=_vmin, vmax=_vmax, outside=_outside,
                yspan=_yspan, d=_d, dist_total=float(_d[-1] - _d[0]))


def _xs_mesh_lines(c, col_step=None):
    """Garis mesh (terrain-following): kurva sejajar permukaan + garis vertikal antar kolom.
    Dikembalikan sebagai (x, y) dengan NaN sbg pemisah -> satu trace / satu plot saja."""
    _xg, _zs, _T = c["xg"], c["zs"], c["T"]
    _col_step = col_step or max(1, len(_xg) // 45)
    _xs_, _ys_ = [], []
    for _dl in list(c["layers"]) + [c["T"]]:
        _xs_ += list(_xg) + [np.nan]
        _ys_ += list(_zs - _dl) + [np.nan]
    for _i in range(0, len(_xg), _col_step):
        _xs_ += [_xg[_i], _xg[_i], np.nan]
        _ys_ += [_zs[_i], _zs[_i] - _T, np.nan]
    return np.array(_xs_), np.array(_ys_)


def _xs_water(c, r):
    """Muka air = titik terendah profil (thalweg) + kedalaman aliran h. Hanya cekungan yg
    menyambung dgn thalweg yg terisi. Return (lo, hi, WL, h) atau None."""
    _h = r.get("flow_depth")
    try:
        _h = float(_h)
    except (TypeError, ValueError):
        return None
    if not np.isfinite(_h) or _h <= 0:
        return None
    _zs = c["zs"]
    _cand = np.where(~c["outside"])[0]
    if len(_cand) == 0:
        _cand = np.arange(len(_zs))
    _it = int(_cand[np.argmin(_zs[_cand])])
    _wl = float(_zs[_it]) + _h
    _lo = _it
    while _lo > 0 and _zs[_lo - 1] < _wl:
        _lo -= 1
    _hi = _it
    while _hi < len(_zs) - 1 and _zs[_hi + 1] < _wl:
        _hi += 1
    if _hi - _lo < 1:
        return None
    return _lo, _hi, _wl, _h


def _xs_plotly_figure(name, r, key="erosion", show_mesh=True, show_water=True,
                      decay=True, thick=None):
    from plotly.subplots import make_subplots

    _avail = _xs_available_params(r)
    if key not in _avail and _avail:
        key = _avail[0]
    _c = _xs_curtain(r, key, decay=decay, thick=thick, nx_max=200, ny=200)
    if _c is None:
        raise ValueError(_t("Data profil tidak cukup untuk menggambar penampang.",
                            "Not enough profile data to draw the section."))
    _strip_keys = [k for k in _avail if k != key][:3]
    _n_strip = len(_strip_keys)
    _main_h, _strip_h = 400, 52
    _height = _main_h + _n_strip * (_strip_h + 14) + 110
    _row_h = [float(_main_h)] + [float(_strip_h)] * _n_strip
    _fig = make_subplots(rows=1 + _n_strip, cols=1, shared_xaxes=True,
                         row_heights=_row_h, vertical_spacing=0.035)

    # ---------- panel utama ----------
    _fig.add_trace(go.Heatmap(x=_c["xg"], y=_c["yc"], z=_c["Zgray"],
                              colorscale=[[0, "#d4d4d4"], [1, "#d4d4d4"]], showscale=False,
                              hoverinfo="skip", zmin=0, zmax=1), row=1, col=1)
    _fig.add_trace(go.Heatmap(x=_c["xg"], y=_c["yc"], z=_c["Z"], colorscale="Jet",
                              zmin=_c["vmin"], zmax=_c["vmax"], hoverinfo="skip",
                              colorbar=dict(title=dict(text=_xs_label(key), side="right"),
                                            thickness=14, x=1.01, xanchor="left")), row=1, col=1)
    if show_mesh:
        _mx, _my = _xs_mesh_lines(_c)
        _fig.add_trace(go.Scatter(x=_mx, y=_my, mode="lines", connectgaps=False,
                                  line=dict(color="rgba(20,20,20,0.38)", width=0.7),
                                  hoverinfo="skip", showlegend=False), row=1, col=1)

    _wat = _xs_water(_c, r) if show_water else None
    if _wat:
        _lo, _hi, _wl, _h = _wat
        _wx = _c["xg"][_lo:_hi + 1]
        _fig.add_trace(go.Scatter(
            x=np.concatenate([_wx, _wx[::-1]]),
            y=np.concatenate([_c["zs"][_lo:_hi + 1], np.full(len(_wx), _wl)]),
            fill="toself", mode="lines", line=dict(color="#0b5cad", width=1),
            fillcolor="rgba(30,144,255,0.60)", hoverinfo="skip", showlegend=False), row=1, col=1)
        _fig.add_annotation(x=float(_wx[len(_wx) // 2]), y=_wl, xref="x", yref="y",
                            text=_t(f"Muka air El. {_wl:.2f} m (h = {_h:.2f} m)",
                                    f"Water level El. {_wl:.2f} m (h = {_h:.2f} m)"),
                            showarrow=True, arrowhead=2, ay=-34, ax=0,
                            font=dict(size=10, color="#0b5cad"), bgcolor="rgba(255,255,255,0.75)")

    # permukaan tanah + hover informatif (semua parameter)
    _idx = np.clip(np.searchsorted(_c["d"], _c["xg"]), 0, len(_c["d"]) - 1)
    _cd_keys = [k for k in _avail]
    _custom = np.column_stack([np.asarray(_xs_param_array(r, k), dtype=float)[_idx] for k in _cd_keys]) \
        if _cd_keys else np.zeros((len(_c["xg"]), 0))
    _hover = "<b>%{x:.0f} m</b><br>" + _t("Elevasi", "Elevation") + ": %{y:.2f} m<br>" + \
        "<br>".join(f"{_xs_label(k)}: %{{customdata[{i}]:.3f}}" for i, k in enumerate(_cd_keys)) + \
        "<extra></extra>"
    _fig.add_trace(go.Scatter(x=_c["xg"], y=_c["zs"], mode="lines",
                              line=dict(color="#111111", width=2.2), customdata=_custom,
                              hovertemplate=_hover, showlegend=False), row=1, col=1)

    _vv = _c["vv"]
    if np.isfinite(_vv).any():
        _im = int(np.nanargmax(_vv))
        _fig.add_trace(go.Scatter(
            x=[_c["xg"][_im]], y=[_c["zs"][_im]], mode="markers",
            marker=dict(symbol="star", size=13, color="white", line=dict(color="black", width=1.2)),
            hovertemplate=_t("Nilai maks. ", "Max value ") + f"{_vv[_im]:.3f}<extra></extra>",
            showlegend=False), row=1, col=1)

    # ---------- strip parameter tambahan ----------
    for _si, _sk in enumerate(_strip_keys):
        _row = 2 + _si
        _sc = _xs_curtain(r, _sk, decay=False, thick=thick, nx_max=240)
        if _sc is None:
            continue
        _z1 = np.where(_sc["outside"], np.nan, _sc["vv"])
        _fig.add_trace(go.Heatmap(x=_sc["xg"], y=[0, 1], z=np.vstack([_z1, _z1]), colorscale="Jet",
                                  zmin=_sc["vmin"], zmax=_sc["vmax"], hoverinfo="skip",
                                  colorbar=dict(thickness=10, x=1.01, xanchor="left",
                                                tickfont=dict(size=9))),
                       row=_row, col=1)
        _fig.update_yaxes(showticklabels=False, showgrid=False, zeroline=False, row=_row, col=1)

    # posisi colorbar mengikuti domain tiap baris
    for _row in range(1, 2 + _n_strip):
        _ya = _fig.layout["yaxis" if _row == 1 else f"yaxis{_row}"]
        _dom = _ya.domain
        _hm = [t for t in _fig.data if isinstance(t, go.Heatmap) and t.showscale is not False
               and t.yaxis == ("y" if _row == 1 else f"y{_row}")]
        for _t_ in _hm:
            _t_.colorbar.len = (_dom[1] - _dom[0])
            _t_.colorbar.y = (_dom[0] + _dom[1]) / 2
            _t_.colorbar.yanchor = "middle"
            _t_.colorbar.lenmode = "fraction"

    for _si, _sk in enumerate(_strip_keys):
        _dom = _fig.layout[f"yaxis{2 + _si}"].domain
        _fig.add_annotation(xref="paper", yref="paper", x=-0.012, y=(_dom[0] + _dom[1]) / 2,
                            xanchor="right", yanchor="middle", text=_xs_short(_sk),
                            showarrow=False, font=dict(size=11, color="#333"))
    _ve = (_c["dist_total"] / 820.0) / ((_c["ymax"] - _c["ymin"]) / float(_main_h))
    _sub = _t(f"Jarak {_c['dist_total']:.0f} m · Relief {_c['yspan']:.1f} m · "
              f"eksagerasi vertikal ≈ {_ve:.1f}× · tebal zona pengaruh {_c['T']:.1f} m",
              f"Length {_c['dist_total']:.0f} m · Relief {_c['yspan']:.1f} m · "
              f"vertical exaggeration ≈ {_ve:.1f}× · influence zone {_c['T']:.1f} m")
    _fig.update_layout(
        title=dict(text=f"<b>{_t('Penampang Melintang', 'Cross Section')} — {name}</b><br>"
                        f"<span style='font-size:12px;color:#555'>{_xs_label(key)} · {_sub}</span>",
                   x=0.01, xanchor="left"),
        height=_height, plot_bgcolor="white", paper_bgcolor="white",
        margin=dict(l=125, r=110, t=78, b=50), showlegend=False,
    )
    _fig.update_yaxes(title_text=_t("Elevasi (m)", "Elevation (m)"), row=1, col=1,
                      range=[_c["ymin"], _c["ymax"]], showgrid=True, gridcolor="rgba(0,0,0,0.08)")
    _fig.update_xaxes(range=[float(_c["xg"][0]), float(_c["xg"][-1])], showgrid=False)
    _fig.update_xaxes(title_text=_t("Jarak (m)", "Distance (m)"), row=1 + _n_strip, col=1)
    return _fig


def _xs_matplotlib_png(name, r, out_path, key="erosion", dpi=200):
    """Versi statis (untuk laporan PDF/DOCX) dari penampang yg sama."""
    import matplotlib.colors as _mc
    from matplotlib.collections import LineCollection

    _avail = _xs_available_params(r)
    if key not in _avail and _avail:
        key = _avail[0]
    _c = _xs_curtain(r, key, decay=True)
    if _c is None:
        return False
    _strip_keys = [k for k in _avail if k != key][:3]
    _n = len(_strip_keys)
    _fig = plt.figure(figsize=(10, 4.6 + 0.62 * _n), constrained_layout=True)
    _gs = _fig.add_gridspec(1 + _n, 1, height_ratios=[6.0] + [0.8] * _n)
    _ax = _fig.add_subplot(_gs[0])
    _ax.pcolormesh(_c["xg"], _c["yc"], np.ma.masked_invalid(_c["Zgray"]),
                   cmap=_mc.ListedColormap(["#d4d4d4"]), shading="auto")
    _pm = _ax.pcolormesh(_c["xg"], _c["yc"], np.ma.masked_invalid(_c["Z"]), cmap="jet",
                         vmin=_c["vmin"], vmax=_c["vmax"], shading="auto")
    _mx, _my = _xs_mesh_lines(_c)
    _ax.plot(_mx, _my, color=(0.08, 0.08, 0.08, 0.38), lw=0.5)
    _wat = _xs_water(_c, r)
    if _wat:
        _lo, _hi, _wl, _h = _wat
        _wx = _c["xg"][_lo:_hi + 1]
        _ax.fill_between(_wx, _c["zs"][_lo:_hi + 1], _wl, color="#1e90ff", alpha=0.65, lw=0)
        _ax.plot([_wx[0], _wx[-1]], [_wl, _wl], color="#0b5cad", lw=1)
        _ax.annotate(f"Muka air El. {_wl:.2f} m (h = {_h:.2f} m)", (_wx[len(_wx) // 2], _wl),
                     xytext=(0, 22), textcoords="offset points", fontsize=7.5, color="#0b5cad",
                     ha="center", arrowprops=dict(arrowstyle="-|>", color="#0b5cad", lw=0.8),
                     bbox=dict(fc="white", ec="none", alpha=0.75, pad=1.5))
    _ax.plot(_c["xg"], _c["zs"], color="#111111", lw=1.6)
    if np.isfinite(_c["vv"]).any():
        _im = int(np.nanargmax(_c["vv"]))
        _ax.plot(_c["xg"][_im], _c["zs"][_im], marker="*", ms=11, mfc="white", mec="black", mew=1)
    _ax.set_ylim(_c["ymin"], _c["ymax"])
    _ax.set_xlim(float(_c["xg"][0]), float(_c["xg"][-1]))
    _ax.set_ylabel("Elevasi (m)", fontsize=9)
    _ax.tick_params(labelsize=8)
    _ax.grid(alpha=0.2, lw=0.4)
    _cb = _fig.colorbar(_pm, ax=_ax, pad=0.01, fraction=0.03)
    _cb.set_label(_xs_label(key), fontsize=8)
    _cb.ax.tick_params(labelsize=7)
    _ve = (_c["dist_total"] / 820.0) / ((_c["ymax"] - _c["ymin"]) / 400.0)
    _ax.set_title(f"Penampang Melintang — {name}\n"
                  f"{_xs_label(key)} · Jarak {_c['dist_total']:.0f} m · Relief {_c['yspan']:.1f} m · "
                  f"eksagerasi vertikal ≈ {_ve:.1f}× · zona pengaruh {_c['T']:.1f} m",
                  fontsize=9, loc="left")
    for _si, _sk in enumerate(_strip_keys):
        _sc = _xs_curtain(r, _sk, decay=False)
        _axs = _fig.add_subplot(_gs[1 + _si], sharex=_ax)
        if _sc is not None:
            _z1 = np.where(_sc["outside"], np.nan, _sc["vv"])
            _p = _axs.pcolormesh(_sc["xg"], [0, 1], np.ma.masked_invalid(np.vstack([_z1, _z1])),
                                 cmap="jet", vmin=_sc["vmin"], vmax=_sc["vmax"], shading="auto")
            _cbs = _fig.colorbar(_p, ax=_axs, pad=0.01, fraction=0.03)
            _cbs.ax.tick_params(labelsize=6)
        _axs.set_yticks([])
        _axs.set_ylabel(_xs_short(_sk), rotation=0, ha="right", va="center", fontsize=8)
        _axs.set_facecolor("#d4d4d4")
        _axs.tick_params(labelsize=7)
        if _si < _n - 1:
            plt.setp(_axs.get_xticklabels(), visible=False)
    (_fig.axes[-1] if _n == 0 else _axs).set_xlabel("Jarak (m)", fontsize=9)
    if _n == 0:
        _ax.set_xlabel("Jarak (m)", fontsize=9)
    _fig.savefig(out_path, dpi=dpi)
    plt.close(_fig)
    return True


def _cover_effective_permeability(layers):
    """Permeabilitas vertikal efektif sistem berlapis (aliran vertikal tegak
    lurus lapisan) -- rata-rata harmonik berbobot tebal, rumus standar untuk
    aliran seri melalui media berlapis: k_eff = sum(t_i) / sum(t_i / k_i)."""
    _tot_t = sum(l["thickness_m"] for l in layers)
    if _tot_t <= 0:
        return 0.0
    _denom = sum(l["thickness_m"] / max(l["permeability_cms"], 1e-15) for l in layers)
    if _denom <= 0:
        return 0.0
    return _tot_t / _denom


def _cover_erosion_verdict(top_layer, slope_angle_deg):
    """Verdict kualitatif ketahanan lapisan PALING ATAS (yang terekspos langsung
    ke erosi permukaan) terhadap kecuraman slope -- pendekatan sederhana: makin
    curam slope, makin besar tau_c yang dibutuhkan supaya tetap aman. Ini alat
    bantu cepat, BUKAN pengganti kajian stabilitas/erosi formal."""
    _tau_c = top_layer.get("tau_c_pa")
    if _tau_c is None:
        return "N/A", "Lapisan ini tidak dirancang terekspos -- pastikan ada lapisan pelindung di atasnya."
    # ambang indikatif: makin curam, makin tinggi tau_c minimum yang disarankan
    _slope_ratio = np.tan(np.radians(slope_angle_deg))  # V:H sebagai desimal
    _tau_needed = 3.0 + _slope_ratio * 30.0  # heuristik linier sederhana, indikatif saja
    if _tau_c >= _tau_needed * 1.3:
        return "AMAN", f"τc lapisan ({_tau_c:.0f} Pa) jauh di atas perkiraan kebutuhan minimum ({_tau_needed:.0f} Pa) untuk kemiringan ini."
    elif _tau_c >= _tau_needed:
        return "MARGINAL", f"τc lapisan ({_tau_c:.0f} Pa) mepet dengan perkiraan kebutuhan minimum ({_tau_needed:.0f} Pa) -- pertimbangkan perkuatan tambahan (mis. erosion blanket, benching)."
    else:
        return "PERLU PERKUATAN", f"τc lapisan ({_tau_c:.0f} Pa) di bawah perkiraan kebutuhan minimum ({_tau_needed:.0f} Pa) untuk kemiringan ini -- risiko erosi permukaan tinggi tanpa perkuatan tambahan."


# =====================================================================
# COVER <-> EROSION MAPPING -- helper penghubung dua arah
# =====================================================================
# Arah 1 (Erosion Mapping -> Cover): tab Surface/Cover membaca slope SEBENARNYA, grain size,
#   metode, kecepatan/kedalaman aliran, tingkat keparahan erosi dari segmen -> perkiraan
#   permeabilitas tanah eksisting + rekomendasi susunan cover.
# Arah 2 (Cover -> Erosion Mapping): cover yang dirancang bisa DITERAPKAN ke segmen; parameter
#   efektif analisis (tau_c / erodibilitas / setara-grain-size / koefisien runoff C) ikut berubah,
#   sehingga hasil analisis erosi berubah. Semua pemetaan bersifat INDIKATIF (lihat catatan UI).

_COVER_THETA_C = 0.047  # parameter Shields kritis (Meyer-Peter & Muller) utk setara-grain-size
_COVER_TOP_CANDIDATES = ("Vegetasi / Topsoil", "Mulsa / Organik", "Growth Medium / Subsoil")


def _cover_estimate_k_from_grain(d_mm):
    """Perkiraan KASAR permeabilitas tanah dari ukuran butir (cm/s). Lempung/lanau: rentang
    tipikal literatur; pasir/kerikil: Hazen k = C*d10^2 dgn d10 ~ 0.6*D50, C=1 (d dlm mm).
    Hanya utk titik awal -- ganti dgn hasil uji lab/lapangan bila ada."""
    d = float(d_mm)
    if d <= 0.002:
        k, sid_, sen_ = 1e-7, "lempung", "clay"
    elif d < 0.063:
        frac = np.log10(d / 0.002) / np.log10(0.063 / 0.002)
        k, sid_, sen_ = 10 ** (-7 + 4 * frac), "lanau", "silt"
    elif d < 2.0:
        k, sid_, sen_ = (0.6 * d) ** 2, "pasir", "sand"
    else:
        k, sid_, sen_ = min((0.6 * d) ** 2, 10.0), "kerikil", "gravel"
    return float(k), sid_, sen_


def _cover_true_slope_stats(seg):
    """Slope SEBENARNYA (dimensionless, tan) dari grid segmen dgn jarak sel yg benar.
    Catatan: array `slope` di hasil analisis = np.gradient(grid_z) tanpa membagi jarak sel,
    jadi satuannya m/sel, bukan m/m -- di sini dihitung ulang dgn spasi grid."""
    try:
        gx = np.asarray(seg["grid_x"], dtype=float)
        gy = np.asarray(seg["grid_y"], dtype=float)
        gz = np.asarray(seg["grid_z"], dtype=float)
        dx = abs(gx[1, 0] - gx[0, 0])
        dy = abs(gy[0, 1] - gy[0, 0])
        if not (dx > 0 and dy > 0):
            return None
        dzx, dzy = np.gradient(gz, dx, dy)
        s = np.hypot(dzx, dzy)
        ins = seg.get("inside")
        mask = np.isfinite(s)
        if ins is not None and np.shape(ins) == s.shape:
            mask &= np.asarray(ins, dtype=bool)
        if mask.sum() < 4:
            return None
        v = s[mask]
        return {
            "mean_tan": float(np.mean(v)), "p95_tan": float(np.percentile(v, 95)),
            "mean_deg": float(np.degrees(np.arctan(np.mean(v)))),
            "p95_deg": float(np.degrees(np.arctan(np.percentile(v, 95)))),
        }
    except Exception:
        return None


def _cover_seg_metrics(seg, grain_override=None):
    """Kumpulkan data segmen Erosion Mapping yg relevan utk perancangan cover."""
    _method = seg.get("analysis_method")
    _grain_meaningful = _method in ("Hjulstrom Diagram", "Shields Diagram")
    _d = grain_override if grain_override else (seg.get("grain_size_mm") if _grain_meaningful else None)
    _st = _cover_true_slope_stats(seg) or {}
    _k = _sid = _sen = None
    if _d:
        _k, _sid, _sen = _cover_estimate_k_from_grain(_d)
    return {
        "label": seg.get("label"), "method": _method, "grain_mm": float(_d) if _d else None,
        "grain_meaningful": _grain_meaningful, "k_est": _k, "soil_id": _sid, "soil_en": _sen,
        "slope_mean_deg": _st.get("mean_deg"), "slope_p95_deg": _st.get("p95_deg"),
        "velocity": seg.get("velocity_hulu"), "flow_depth": seg.get("flow_depth"),
        "max_zone": float(seg.get("max_zone", 0.0) or 0.0),
        "erosion_ratio": float(seg.get("erosion_ratio", 0.0) or 0.0),
        "tau_critical": seg.get("tau_critical_base", seg.get("tau_critical")),
        "erodibility_M": seg.get("erodibility_M_base", seg.get("erodibility_M")),
    }


def _cover_recommend(m):
    """Rekomendasi cover berbasis aturan (transparan): tau_c minimum indikatif dari slope
    x keparahan erosi x jenis tanah x kecepatan aliran, plus saran permeabilitas dari grain size."""
    _deg = m.get("slope_p95_deg") or m.get("slope_mean_deg") or 18.0
    _base_need = 3.0 + np.tan(np.radians(_deg)) * 30.0  # sama dgn heuristik _cover_erosion_verdict
    _mz = m.get("max_zone", 0.0)
    _sev = 1.0 if _mz < 0.5 else 1.2 if _mz < 1.0 else 1.5 if _mz < 1.8 else 2.0
    _d = m.get("grain_mm")
    if _d is None:
        _soilf = 1.0
    else:
        _soilf = 1.0 if _d < 0.002 else 1.3 if _d < 0.25 else 1.1 if _d < 2.0 else 0.9
    _v = m.get("velocity")
    _velf = 1.2 if (_v is not None and _v > 1.5) else 1.0
    _tau_need = float(_base_need * _sev * _soilf * _velf)

    _cands = sorted(
        [(n, COVER_MATERIAL_PRESETS[n]["tau_c_pa"]) for n in _COVER_TOP_CANDIDATES
         if COVER_MATERIAL_PRESETS[n]["tau_c_pa"] is not None],
        key=lambda c: c[1])
    _ok = [c for c in _cands if c[1] >= _tau_need]
    _met = bool(_ok)
    _top = _ok[0][0] if _ok else _cands[-1][0]

    _k = m.get("k_est")
    _thick_top = 0.40 if _sev >= 1.5 else 0.30
    _stack = [{"material": _top, "thickness_m": _thick_top}]
    if _top != "Growth Medium / Subsoil":
        _stack.append({"material": "Growth Medium / Subsoil", "thickness_m": 0.50})
    if _k is not None and _k >= 1e-3:
        _stack.append({"material": "Clay / Subsoil Barrier", "thickness_m": 0.60})

    _b = []
    _b.append(_t(
        f"τc minimum indikatif ≈ **{_tau_need:.0f} Pa** (dasar slope {_base_need:.0f} Pa × keparahan erosi "
        f"{_sev:.1f} × jenis tanah {_soilf:.1f} × kecepatan {_velf:.1f}). Lapisan terekspos yang disarankan: "
        f"**{_top}** (τc {COVER_MATERIAL_PRESETS[_top]['tau_c_pa']:.0f} Pa).",
        f"Indicative minimum τc ≈ **{_tau_need:.0f} Pa** (slope base {_base_need:.0f} Pa × erosion severity "
        f"{_sev:.1f} × soil type {_soilf:.1f} × velocity {_velf:.1f}). Suggested exposed layer: "
        f"**{_top}** (τc {COVER_MATERIAL_PRESETS[_top]['tau_c_pa']:.0f} Pa).",
    ))
    if not _met:
        _b.append(_t(
            f"⚠ Tidak ada preset yang mencapai {_tau_need:.0f} Pa -- pertimbangkan erosion control blanket, "
            "geocell, atau riprap ringan pada lapisan terekspos, lalu isi τc-nya lewat 'Properti (bisa ditimpa)'.",
            f"⚠ No preset reaches {_tau_need:.0f} Pa -- consider an erosion control blanket, geocell or light "
            "riprap on the exposed layer, then enter its τc under 'Properties (overridable)'."))
    if _k is not None:
        _sid, _sen = m.get("soil_id"), m.get("soil_en")
        if _k < 1e-5:
            _b.append(_t(
                f"Tanah eksisting ≈ **{_sid}** (k ≈ {_k:.1e} cm/s): infiltrasi rendah → limpasan tinggi. "
                "Tambahkan lapisan permeabel di atas (topsoil/mulsa, k ≥ 1e-4 cm/s, tebal ≥ 0,3 m) agar hujan "
                "meresap & percikan hujan teredam; barrier lempung tambahan tidak diperlukan.",
                f"Existing soil ≈ **{_sen}** (k ≈ {_k:.1e} cm/s): low infiltration → high runoff. Add a permeable "
                "layer on top (topsoil/mulch, k ≥ 1e-4 cm/s, ≥ 0.3 m thick) so rain infiltrates and rainsplash is "
                "damped; an extra clay barrier is not needed."))
        elif _k < 1e-3:
            _b.append(_t(
                f"Tanah eksisting ≈ **{_sid}** (k ≈ {_k:.1e} cm/s): infiltrasi sedang -- topsoil bervegetasi "
                "di atas growth medium sudah memadai.",
                f"Existing soil ≈ **{_sen}** (k ≈ {_k:.1e} cm/s): moderate infiltration -- vegetated topsoil "
                "over a growth medium is adequate."))
        else:
            _b.append(_t(
                f"Tanah eksisting ≈ **{_sid}** (k ≈ {_k:.1e} cm/s): infiltrasi tinggi tapi butir lepas mudah "
                "tergerus jika terekspos → tutup dengan topsoil bervegetasi; barrier lempung 0,6 m di bawahnya "
                "menahan lengas & mengurangi perkolasi (sudah disertakan di susunan yang disarankan).",
                f"Existing soil ≈ **{_sen}** (k ≈ {_k:.1e} cm/s): high infiltration but loose grains scour easily "
                "if exposed → cover with vegetated topsoil; a 0.6 m clay barrier below retains moisture and reduces "
                "percolation (included in the suggested stack)."))
    else:
        _b.append(_t(
            "Grain size tidak tersedia dari metode analisis ini -- isi D50 tanah eksisting di atas untuk "
            "mendapat saran permeabilitas.",
            "Grain size is not available from this analysis method -- enter the existing soil D50 above to "
            "get permeability advice."))
    if _deg >= 25:
        _b.append(_t(
            f"Slope ≈ {_deg:.0f}° (curam): pertimbangkan benching/teras & saluran pinggir; di atas ±34° "
            "perlu perkuatan geosintetik.",
            f"Slope ≈ {_deg:.0f}° (steep): consider benching/terracing and toe drains; above ≈34° "
            "geosynthetic reinforcement is needed."))
    return {"tau_needed": _tau_need, "top_material": _top, "met": _met, "stack": _stack, "bullets": _b}


def _cover_runoff_c(k_eff_cms):
    """Koefisien runoff Rasional dari permeabilitas efektif cover: 0.90 (k <= 1e-7) s/d 0.25 (k >= 1e-2),
    interpolasi log-linear. Indikatif; pakai k_eff (kondisi jenuh/konservatif)."""
    _lk = np.log10(max(float(k_eff_cms), 1e-12))
    return float(0.90 - 0.65 * np.clip((_lk + 7.0) / 5.0, 0.0, 1.0))


def _cover_map_to_params(snap, method, grain_size_mm, rho_water, rho_soil,
                         tau_critical, erodibility_M, runoff_c):
    """Petakan cover terapan -> parameter efektif analisis (dipakai loop analisis & preview)."""
    _out = {"active": False, "grain_size_eff": float(grain_size_mm), "vfac": 1.0,
            "tau_critical": float(tau_critical), "erodibility_M": float(erodibility_M),
            "runoff_c": float(runoff_c), "tau_base_pa": None, "effects": []}
    _g = 9.81
    _top_tau = snap.get("top_tau")
    if snap.get("use_tau", True) and _top_tau:
        if method == "Hjulstrom Diagram":
            _tb = _COVER_THETA_C * (rho_soil - rho_water) * _g * (grain_size_mm / 1000.0)
            _out["tau_base_pa"] = float(_tb)
            _out["vfac"] = float(np.clip(np.sqrt(max(_tb, 1e-9) / max(_top_tau, 1e-6)), 0.02, 3.0))
            _out["effects"].append("vfac")
        elif method == "Shields Diagram":
            _out["grain_size_eff"] = float(_top_tau / (_COVER_THETA_C * (rho_soil - rho_water) * _g) * 1000.0)
            _out["effects"].append("grain")
        else:
            _out["tau_critical"] = float(_top_tau)
            _out["erodibility_M"] = float(np.clip(erodibility_M * (tau_critical / _top_tau) ** 0.5, 1e-4, 10.0))
            _out["effects"].append("tau")
        _out["active"] = True
    if snap.get("use_perm", True) and snap.get("k_eff"):
        _out["runoff_c"] = _cover_runoff_c(snap["k_eff"])
        _out["effects"].append("runoff")
        _out["active"] = True
    return _out


def _cover_apply_to_erosion_cb():
    """Callback tombol 'Terapkan ke Erosion Mapping' (callback jalan SEBELUM widget dibuat, jadi
    aman mengubah state checkbox per-segmen di tab Erosion Mapping)."""
    layers = [dict(l) for l in (st.session_state.get("cover_layers") or [])]
    if not layers:
        return
    _sids_all = list(st.session_state.get("segments", []))
    _picked = [s for s in (st.session_state.get("cover_apply_sids") or []) if s in _sids_all]
    st.session_state["cover_applied"] = {
        "layers": layers, "top_material": layers[0].get("material"), "top_tau": layers[0].get("tau_c_pa"),
        "k_eff": float(_cover_effective_permeability(layers)),
        "total_t": float(sum(l["thickness_m"] for l in layers)),
        "slope_deg": float(st.session_state.get("cover_slope_angle", 18.0)),
        "use_tau": bool(st.session_state.get("cover_use_tau", True)),
        "use_perm": bool(st.session_state.get("cover_use_perm", True)),
        "sids": _picked,
    }
    for _s in _sids_all:
        st.session_state[f"cover_toggle_{_s}"] = _s in _picked


def _cover_release_from_erosion_cb():
    st.session_state.pop("cover_applied", None)
    for _s in st.session_state.get("segments", []):
        st.session_state[f"cover_toggle_{_s}"] = False


def _cover_toggle_cb(sid):
    snap = st.session_state.get("cover_applied")
    if not snap:
        return
    _s = set(snap.get("sids", []))
    if st.session_state.get(f"cover_toggle_{sid}"):
        _s.add(sid)
    else:
        _s.discard(sid)
    snap["sids"] = sorted(_s)




