                        """
                        <button id="dlb" style="width:100%%;padding:8px 12px;border-radius:6px;
                            border:1px solid #888;background:#2E5C31;color:#fff;font-weight:600;
                            cursor:pointer;font-family:sans-serif;">
                            ⬇ Download Project (cara alternatif)
                        </button>
                        <div id="dlm" style="font:12px sans-serif;margin-top:4px;color:#ccc;"></div>
                        <script>
                        const B64 = "%s";
                        const FNAME = "%s";
                        document.getElementById("dlb").onclick = async function () {
                            try {
                                const r = await fetch("data:application/octet-stream;base64," + B64);
                                const blob = await r.blob();
                                const a = document.createElement("a");
                                a.href = URL.createObjectURL(blob);
                                a.download = FNAME;
                                document.body.appendChild(a);
                                a.click();
                                setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 2000);
                                document.getElementById("dlm").textContent = "Mengunduh " + FNAME + " ...";
                            } catch (e) {
                                document.getElementById("dlm").textContent = "Gagal: " + e;
                            }
                        };
                        </script>
                        """ % (_b64_str, _dl_fname),
